<script setup>
import { ref } from 'vue'
import { useRouter } from 'vue-router'
import { useAuthStore } from '@/stores/auth'
const email=ref(''),submittedEmail=ref(''),loading=ref(false),error=ref(''),success=ref(false);const authStore=useAuthStore(),router=useRouter();const sendResetLink=async()=>{error.value='';success.value=false;const normalizedEmail=email.value.trim().toLowerCase();if(!normalizedEmail){error.value='Enter the email address linked to your account.';return}loading.value=true;try{await authStore.forgotPassword(normalizedEmail);submittedEmail.value=normalizedEmail;success.value=true}catch(err){error.value=err.message||'We couldn’t send the reset link. Please try again.'}finally{loading.value=false}};const goToLogin=()=>router.push('/login')
</script><template><div class="forgot-password-form"><template v-if="success"><h1>Check your email</h1><p>If an account exists for <strong>{{submittedEmail}}</strong>, we’ve sent a password reset link.</p><p>It may take a minute to arrive. Check your spam folder too.</p><button class="quiet" @click="goToLogin">Back to log in</button></template><template v-else><h1>Reset your password</h1><p>Enter the email linked to your account. We’ll send you a link to choose a new password.</p><p v-if="error" class="error">{{error}}</p><form @submit.prevent="sendResetLink"><label>Email address<input v-model="email" type="email" autocomplete="email" required></label><button class="primary" :disabled="loading">{{loading?'Sending your link...':'Send reset link'}}</button></form><button class="quiet" @click="goToLogin">Back to log in</button></template></div></template><style scoped>.forgot-password-form{color:var(--color-text)}h1{text-align:center;font-size:1.65rem}p{color:var(--color-muted);line-height:1.6;text-align:center}strong{color:var(--color-text)}label{display:grid;gap:7px;margin:24px 0 17px;font-size:.82rem;font-weight:650}input{min-height:48px;padding:0 14px;border:1px solid var(--color-border);border-radius:10px;background:var(--color-bg);color:var(--color-text);font:inherit}.primary{width:100%;min-height:48px;border:0;border-radius:999px;background:var(--color-accent);color:#fff;font:inherit;font-weight:750}.quiet{width:100%;margin-top:14px;border:0;background:transparent;color:var(--color-muted);font:inherit;cursor:pointer}.error{padding:11px;border:1px solid var(--color-border);border-radius:9px;color:#dc5f6d}</style>
